[6031] = { en = "Runecloth", tier = 4,
  t = "Runecloth",
  d = "In Timbermaw zijn we tevreden. We houden niet van vreemden. Dat is goed voor ons, maar slecht voor de handel.$B$BNiet lang geleden kwam er een zeldzame vriendin naar Timbermaw, een nachtelf. Ze droeg een mantel van runecloth. Runecloth is zeldzaam bij ons, maar de mantel was zo mooi dat mijn volk wil dat ik meer kleding van runecloth maak.$B$BWil je me runecloth brengen? Als je genoeg brengt, geef ik je er iets voor terug.",
  o = "Breng 30 Runecloth naar Meilosh in Timbermaw Hold.",
  p = "Heb je de runecloth? Mijn volk wil graag meer spullen van runecloth!",
  c = "Ah, je hebt de stof gebracht. Wat een mooi materiaal!$B$BDank je, $N. Je bent een echte $gvriend:vriendin;. Neem dit aan als ruil.",
  g = { {"tevreden", "content"}, {"vreemden", "strangers (vreemde)"}, {"handel", "trade"}, {"zeldzame", "rare (zeldzaam)"}, {"mantel", "cloak"}, {"kleding", "clothing"}, {"spullen", "items, things"}, {"stof", "cloth"}, {"ruil", "exchange, trade"} },
},

[6032] = { en = "Sacred Cloth", tier = 4,
  t = "Heilige stof",
  d = "Het volk van Timbermaw geniet van hoe runecloth aanvoelt, maar het is niet heilig voor ons. Mooncloth wel.$B$BBreng me een kleine voorraad van deze heilige stof, dan leer ik je een geheime techniek om iets te maken.",
  o = "Breng 2 Mooncloth naar Meilosh in Timbermaw Hold.",
  p = "Heb je de mooncloth gebracht, $N?",
  c = "Ah, heel goed. Deze mooncloth wordt gebruikt voor kleding die heilig is voor ons volk. Dank je, $N. Nu zal ik je trainen.",
  g = { {"Heilige", "sacred, holy (heilig)"}, {"geniet", "delights (genieten)"}, {"aanvoelt", "feels (aanvoelen)"}, {"voorraad", "supply"}, {"geheime", "secret (geheim)"}, {"techniek", "technique"}, {"trainen", "to train"} },
},

[7489] = { en = "Lethtendris's Web", tier = 4,
  t = "Het web van Lethtendris",
  d = "De bloedelf Lethtendris is te ver gegaan. Ze wilde zo graag magische kracht verzamelen dat ze tegen haar volksgenoten inging en een apparaat bouwde met een verraderlijk ontwerp: een web dat de besmette magische energie van Dire Maul moet wegzuigen. Zelfs nu verzamelt ze die energie, en ze is van plan die los te laten op haar vijanden.$B$BLethtendris moet worden tegengehouden. Zoek haar in het Warpwood Quarter van Dire Maul, versla haar en breng haar web naar mij, zodat het teruggegeven kan worden aan bloedelfen met een helderder hoofd, die het kunnen bestuderen.",
  o = "Breng Lethtendris's Web naar Talo Thornhoof in Camp Mojache in Feralas.",
  p = "$N, heb je Lethtendris's Web?",
  c = "Je hebt het goed gedaan, $N. Dit web bevat enorme voorraden van de magie van Dire Maul, en ik ben bang voor de schade die kan ontstaan als iemand zo onverantwoordelijk als Lethtendris die energie zou benutten. Haar dood maakt me verdrietig, maar ik weet dat ze haar web nooit had opgegeven zolang ze leefde.$b$bDank je, $N. Ik stuur het web naar studenten van de magie die verantwoordelijker zijn dan Lethtendris. Zij worden de nieuwe bewakers van de kracht ervan.",
  g = { {"bloedelf", "blood elf"}, {"te ver gegaan", "overstepped her bounds (te ver gaan)"}, {"volksgenoten", "brethren, own people"}, {"inging", "defied (ingaan tegen)"}, {"verraderlijk ontwerp", "insidious design"}, {"besmette", "tainted (besmet)"}, {"wegzuigen", "to siphon off"}, {"los te laten", "to release (loslaten)"}, {"tegengehouden", "stopped (tegenhouden)"}, {"helderder hoofd", "clearer head"}, {"onverantwoordelijk", "irresponsible"}, {"benutten", "to harness, use"}, {"opgegeven", "given up (opgeven)"}, {"bewakers", "wardens (bewaker)"} },
},

[7492] = { en = "Camp Mojache", tier = 4,
  t = "Camp Mojache",
  d = "Talo Thornhoof, een tauren-oudere in Feralas, vraagt om hulp. Hij gaf weinig details, maar hij zei wel dat hij agenten nodig heeft voor een zaak die zowel gevoelig... als ernstig is.$B$BDien de Horde, $N. Ga naar Camp Mojache in Feralas en spreek met Talo.",
  o = "Spreek met Talo Thornhoof in Camp Mojache in Feralas.",
  c = "Ah, het is goed dat een $C gehoor geeft aan mijn oproep. Ik heb je diensten nodig, $N, en ik vrees dat ze je langs een gevaarlijk pad zullen leiden...$b$bEen pad naar Dire Maul.",
  g = { {"oudere", "elder"}, {"agenten", "agents (agent)"}, {"zaak", "matter"}, {"gevoelig", "delicate"}, {"ernstig", "dire, serious"}, {"Dien", "serve (dienen)"}, {"gehoor geeft aan", "heeds (gehoor geven aan)"}, {"oproep", "summons, call"}, {"vrees", "fear (vrezen)"} },
},

[6847] = { en = "Master Ryson's All Seeing Eye", tier = 4,
  t = "Het Alziende Oog van Master Ryson",
  d = "Jullie oorlog in het hart van Alterac betekent niets voor het Syndicate, $c. Wij doen wat we altijd hebben gedaan: wachten tot er een duidelijke winnaar opstaat uit de as en het puin van deze waanzin, en dan toeslaan.$B$BMaar daarom zijn we hier nu niet. Het Alziende Oog is verloren gegaan. De Winterax-trollen uit deze streek hebben het meegenomen.$B$BHaal het Oog terug, dan staan onze diensten tot jouw beschikking - voor de tijd die jouw kant nog rest.$B$BKom terug bij mij zodra je het oog hebt, zodat ik je kan onderzoeken.$B$B<Master Ryson grijnst.>",
  o = "Haal Master Ryson's All Seeing Eye terug uit de grotten van de Winterax en breng het naar Master Ryson.$B$BPas op: men zegt dat Master Ryson's All Seeing Eye een vreselijke vloek met zich meedraagt!",
  e = "Master Ryson's All Seeing Eye teruggevonden",
  g = { {"Alziende", "all-seeing"}, {"as", "ashes"}, {"puin", "rubble"}, {"waanzin", "madness"}, {"toeslaan", "to strike"}, {"diensten", "services (dienst)"}, {"tot jouw beschikking", "at your disposal"}, {"rest", "remains (resten)"}, {"grijnst", "grins (grijnzen)"}, {"vloek", "curse"}, {"meedraagt", "carries along (meedragen)"} },
},

[6861] = { en = "Zinfizzlex's Portable Shredder Unit", tier = 4,
  t = "De draagbare shredder van Zinfizzlex",
  p = "Ik wil net zo graag als jij mijn draagbare shredder uitproberen, $r, maar voordat ik de bouwdoos kan maken, heb ik materiaal nodig - heel veel materiaal! $b$bOm precies te zijn: ik heb een berg thorium, mithril en ijzer nodig. Ook heb ik per apparaat één stoomzaag nodig. Die moet je bij de houtzagerij halen. $b$bToen ik hier rondsnuffelde (voordat ik gevangen werd), zag ik een stapel stoomzagen bij het houthakkerskamp van de Stormpike. $b$bMaster Engineer Zinfizzlex wil dat je hem het volgende brengt:",
  g = { {"draagbare", "portable (draagbaar)"}, {"uitproberen", "to try out"}, {"bouwdoos", "kit"}, {"apparaat", "device, unit"}, {"stoomzaag", "steamsaw"}, {"stoomzagen", "steamsaws"}, {"houtzagerij", "lumber mill"}, {"rondsnuffelde", "nosed around (rondsnuffelen)"}, {"stapel", "pile"}, {"houthakkerskamp", "lumber camp"} },
},

[6901] = { en = "Launch the Attack!", tier = 4,
  t = "Begin de aanval!",
  p = "Mijn troepen hebben hun voorraden en zijn klaar voor de aanval. We wachten alleen nog op bevelen van de Frostwolf Quartermaster, dan stuur ik ze de strijd in!",
  c = "Werd tijd! Nu kunnen we de Alliance laten zien hoe dwaas het was om naar Alterac Valley te komen!",
  g = { {"troepen", "troops (troep)"}, {"voorraden", "supplies (voorraad)"}, {"bevelen", "orders (bevel)"}, {"Werd tijd", "about time"}, {"dwaas", "foolish"} },
},

[7001] = { en = "Empty Stables", tier = 4,
  t = "Lege stallen",
  d = "De oorlog in de vallei heeft onze soldaten zwaar getroffen. We moeten onze troepen nieuwe kracht geven!$B$BAls we de stallen kunnen vullen, kunnen de Wolf Riders weer het slagveld op rijden.$B$BNeem deze muilkorf en spoor de frostwolven op die in het bos hier in de buurt leven. Als je een wolf vindt, gebruik dan de muilkorf om het beest te temmen. Breng het getemde beest terug naar mij, zodat ik het in de stal kan zetten.$B$BAls we genoeg wolven in de stal hebben, gaan de Wolf Riders weer op patrouille aan onze frontlinie.",
  o = "Zoek een Frostwolf in Alterac Valley. Gebruik de Frostwolf Muzzle als je dicht bij de Frostwolf bent om het beest te 'temmen'. Als het getemd is, volgt de Frostwolf je terug naar de Frostwolf Stable Master. Spreek met de Frostwolf Stable Master om de vangst op je naam te krijgen.",
  p = "Zonder jouw hulp zouden de Frostwolf Wolf Riders geen rijdieren hebben om mee ten strijde te trekken. Je bewijst ons een grote dienst!",
  c = "Ik kan alleen maar hopen dat de soldaten die ramshuiden moeten verzamelen net zo vastberaden zijn als jij, $N.$B$BIn dit tempo zijn de stallen binnen een paar uur vol!",
  e = "Frostwolf gemuilkorfd en teruggebracht",
  g = { {"zwaar getroffen", "taken a heavy toll"}, {"stallen", "stables (stal)"}, {"slagveld", "battlefield"}, {"muilkorf", "muzzle"}, {"spoor", "track (opsporen)"}, {"temmen", "to tame"}, {"getemde", "tamed (temmen)"}, {"frontlinie", "front line"}, {"rijdieren", "mounts (rijdier)"}, {"ten strijde te trekken", "to ride into battle"}, {"ramshuiden", "ram hides (ramshuid)"}, {"vastberaden", "determined"}, {"gemuilkorfd", "muzzled (muilkorven)"} },
},

[7002] = { en = "Ram Hide Harnesses", tier = 4,
  t = "Tuigen van ramshuid",
  d = "Terwijl sommige van onze soldaten wolven vangen voor de stalmeester, moeten anderen zorgen voor de eenvoudige dingen die je nodig hebt om te rijden. Ik bedoel natuurlijk tuigen om mee te rijden.$B$BJe moet de rammen aanvallen die hier in de streek leven. Precies dezelfde rammen die de ruiterij van de Stormpike als rijdier gebruikt!$B$BDood ze en kom bij mij terug met hun huiden. Zodra we genoeg huiden hebben verzameld, maken we er tuigen van voor de ruiters. De Frostwolf Wolf Riders zullen weer rijden!",
  o = "null",
  p = "Dood ze en kom bij mij terug met hun huiden. Dezelfde rammen die de ruiterij van de Stormpike als rijdier gebruikt!",
  c = "Goed gedaan, soldaat. Ik laat het je weten als ik genoeg huiden heb verzameld.$B$BGa door!",
  g = { {"tuigen", "harnesses (tuig)"}, {"ramshuid", "ram hide"}, {"stalmeester", "stable master"}, {"rammen", "rams (ram)"}, {"ruiterij", "cavalry"}, {"rijdier", "mount"}, {"huiden", "hides (huid)"}, {"ruiters", "riders (ruiter)"} },
},

[7082] = { en = "The Graveyards of Alterac", tier = 4,
  t = "De begraafplaatsen van Alterac",
  d = "De frontlinies van Alterac Valley verschuiven steeds. Gebieden wisselen heen en weer als we onze vijanden in dodelijke gevechten ontmoeten. En op begraafplaatsen, $N, woedt de strijd het hevigst.$B$BIk wil dat je een begraafplaats van de Alliance aanvalt! Zoek een begraafplaats met een banier van de Alliance in het midden en trek die uit de grond.$B$BDoe dat, en je taak voor mij is klaar, maar... als je de begraafplaats een paar minuten vasthoudt, wordt hij van ons en komen er troepen om je af te lossen.",
  o = "Val een begraafplaats aan en keer dan terug naar Corporal Teeka Bloodsnarl in de Alterac Mountains.",
  p = "Val een begraafplaats aan die in handen is van de Alliance!",
  c = "Goed gedaan, $N! Met elke begraafplaats die wij beheersen, dwalen de geesten van onze vijanden nog verlorener en doellozer rond.",
  o1 = "Begraafplaats aangevallen",
  g = { {"begraafplaatsen", "graveyards (begraafplaats)"}, {"verschuiven", "shift"}, {"woedt", "rages (woeden)"}, {"hevigst", "fiercest (hevig)"}, {"banier", "banner"}, {"af te lossen", "to relieve (aflossen)"}, {"beheersen", "control"}, {"dwalen", "wander"}, {"doellozer", "more aimless (doelloos)"} },
},

[7101] = { en = "Towers and Bunkers", tier = 4,
  t = "Torens en bunkers",
  d = "Torens en bunkers zijn belangrijke posities, en we moeten ze allemaal veroveren en vasthouden! Daarom wil ik dat je een bunker aanvalt die in handen is van de vijand.$B$BGa daarvoor een bunker binnen met een banier van de Alliance. Binnen zie je nog een banier. Trek die banier eruit, en er verschijnt een witte banier van de Horde op die plek. Goed gedaan!$B$BDan is je taak voor mij klaar, maar als je de plek lang genoeg vasthoudt, en als de Alliance hem niet terugpakt, dan wordt hij vernietigd!",
  o = "Verover een vijandelijke toren en keer dan terug naar Corporal Teeka Bloodsnarl in de Alterac Mountains.",
  p = "Je hebt nog geen bunker aangevallen, $N! Wacht je tot anderen jouw roem opeisen?",
  c = "Ik hoorde dat je missie is gelukt! Dat bevalt me...$B$BOnze troepen kunnen nu ongestraft naar voren stormen en de Alliance laten zien dat Alterac Valley geen plek voor hen is!",
  o1 = "Toren veroverd",
  g = { {"veroveren", "to capture, conquer"}, {"vasthouden", "to hold"}, {"verschijnt", "appears (verschijnen)"}, {"vernietigd", "destroyed (vernietigen)"}, {"vijandelijke", "enemy (adj.)"}, {"roem", "glory"}, {"opeisen", "to claim"}, {"bevalt", "pleases (bevallen)"}, {"ongestraft", "with impunity"} },
},

[7123] = { en = "Speak with our Quartermaster", tier = 4,
  t = "Spreek met onze kwartiermeester",
  d = "$N, de Frostwolf Quartermaster zoekt rekruten voor taken die naar de mijnen van Alterac Valley leiden. Spreek met hem; hij vertelt je meer.$B$BVolg de weg naar het westen tot in de bunker, neem dan de westelijke uitgang, en daar vind je onze kwartiermeester.",
  o = "Spreek met de Frostwolf Quartermaster.",
  c = "Gegroet, $N! Het is goed om een $c zoals jij te zien, die graag $gzijn:haar; deel doet voor de Horde. Spreek me nog eens aan, want ik heb belangrijke taken voor je...",
  g = { {"kwartiermeester", "quartermaster"}, {"rekruten", "recruits (rekruut)"}, {"mijnen", "mines (mijn)"}, {"westelijke", "western, west"}, {"uitgang", "exit"}, {"Gegroet", "hail, greetings"} },
},

[7124] = { en = "Capture a Mine", tier = 4,
  t = "Verover een mijn",
  d = "Terwijl de strijd over het landschap van Alterac Valley woedt, woedt hij ook in de Coldtooth- en Irondeep-mijnen. Beide zijn rijke bronnen van mineralen, en in beide worden voorraden bewaard; geen wonder dat ze zo waardevol zijn!$B$BHelp ons in de oorlog, $N! Verover een van de mijnen voor de Horde! Ga daarvoor een mijn binnen die niet van ons is en dood de leider. Daarna is de mijn van ons en sturen we troepen om hem te beschermen!",
  o = "Verover een mijn en keer dan terug naar Corporal Teeka Bloodsnarl in de Alterac Mountains.",
  p = "Je hebt nog geen mijn veroverd, $N! Zoek er een die niet van ons is en versla de leider!",
  c = "Je hebt een mijn veroverd! Nu onze eigen krijgers hem beschermen, wordt het veel makkelijker om mineralen uit de diepte te halen of voorraden te verzamelen die er verborgen liggen.$B$BGoed gedaan, $N. Wat je hebt gedaan is een grote hulp voor onze strijd.",
  o1 = "Mijn veroverd",
  g = { {"Verover", "capture (veroveren)"}, {"landschap", "landscape"}, {"bronnen", "sources (bron)"}, {"mineralen", "minerals (mineraal)"}, {"bewaard", "stored (bewaren)"}, {"waardevol", "valuable"}, {"versla", "defeat (verslaan)"}, {"diepte", "depth(s)"}, {"verborgen", "hidden, cached"} },
},

[7142] = { en = "The Battle for Alterac", tier = 4,
  t = "De strijd om Alterac",
  d = "De Stormpike-dwergen en hun bondgenoten zijn Alterac Valley binnengevallen, en we moeten ze verdrijven! Om de strijd om Alterac te winnen, moeten we hun generaal verslaan: Vanndar Stormpike!$B$BJe vindt Vanndar in Dun Baldar, in het noorden van Alterac Valley.$B$BVernietig hem, $N, en kom dan terug bij mij.",
  o = "Ga Alterac Valley binnen en versla de dwergengeneraal Vanndar Stormpike. Keer daarna terug naar Voggah Deathgrip in de Alterac Mountains.",
  p = "We dulden de dwergen niet in ons thuisland! Val onze vijanden aan en versla hun leider, generaal Stormpike!",
  c = "Goed gedaan, $N! De Stormpikes hebben geen enkele hoop in deze dwaze invasie.$B$BHa! Tot nu toe hebben ze alleen hun eigen generaal laten doden!",
  e = "Versla Vanndar Stormpike.",
  g = { {"bondgenoten", "allies (bondgenoot)"}, {"binnengevallen", "invaded (binnenvallen)"}, {"verdrijven", "to drive out"}, {"verslaan", "to defeat"}, {"dwergengeneraal", "dwarven general"}, {"dulden", "tolerate, suffer"}, {"thuisland", "homeland"}, {"dwaze", "foolish (dwaas)"} },
},

[7161] = { en = "Proving Grounds", tier = 4,
  t = "Proefterrein",
  d = "Gegroet, $c. Het is lang geleden dat we de roep van de strijd konden beantwoorden. De oude gevoelens komen langzaam op, maar als ze eenmaal wakker zijn, stroomt het bloed snel. De strijdwoede keert terug...$B$BAlle nieuwkomers in de Vallei moeten eerst het strijdritueel voltooien.$B$BDiep in de grot van de Wildpaw-gnolls ligt een banier van de Frostwolf. Trek erop uit en haal de banier terug. Breng hem naar mij, dan geef ik je het insigne van een Frostwolf-ingewijde.",
  o = "Reis naar de Wildpaw-grot ten zuidoosten van de hoofdbasis in Alterac Valley en zoek de Frostwolf Banner. Breng de Frostwolf Banner terug naar Warmaster Laggrond.",
  p = "Word wakker! Word wakker, $N! Dit is geen droom. Je zit echt midden in een woedende strijd!",
  c = "Dat brandende gevoel is je ziel die ontwaakt. Je geest heeft de oproep tot de wapens aanvaard.$B$BJe bent nu een van de Frostwolf, $N. Gefeliciteerd.$B$BDraag dit insigne altijd bij je. Als je hoger komt in de rangen van de Frostwolf, vervang ik het insigne door andere, krachtigere insignes.$B$BMisschien word je ooit tot de hoogste eer verheven bij de Frostwolf Clan. Als die dag ooit komt, krijg je het Eye of Command.",
  g = { {"Proefterrein", "proving ground"}, {"roep", "call"}, {"stroomt", "rushes, flows (stromen)"}, {"strijdwoede", "battle rage"}, {"strijdritueel", "rite of battle"}, {"voltooien", "to complete"}, {"Trek erop uit", "venture forth (erop uittrekken)"}, {"insigne", "insignia"}, {"ingewijde", "initiate"}, {"woedende", "raging (woeden)"}, {"ontwaakt", "awakens (ontwaken)"}, {"aanvaard", "accepted (aanvaarden)"}, {"rangen", "ranks (rang)"}, {"verheven", "raised, exalted (verheffen)"} },
},

[7163] = { en = "Rise and Be Recognized", tier = 4,
  t = "Sta op en word erkend",
  p = "<Warmaster Laggrond salueert.>$B$BHet is jouw tijd, $N. Je hebt veel gedaan voor de Frostwolf Clan, en daarmee heb je een plaats verdiend, niet alleen als soldaat van de Frostwolf, maar ook als vriend.$B$BGoed gedaan! Laat je ingewijdeninsigne zien.$B",
  c = "Dit nieuwe insigne laat je rang onder de Frostwolf zien. Draag het altijd bij je.$B$BEn, $C... sterf met eer!",
  g = { {"erkend", "recognized (erkennen)"}, {"salueert", "salutes (salueren)"}, {"verdiend", "earned (verdienen)"}, {"ingewijdeninsigne", "initiate's insignia"}, {"rang", "rank"}, {"sterf", "die (sterven)"}, {"eer", "honor"} },
},

[7164] = { en = "Honored Amongst the Clan", tier = 4,
  t = "Geëerd binnen de clan",
  p = "Het is goed je weer te zien, $C. Ik had niet verwacht dat je terug zou komen. Maar je hebt bewezen dat je een dappere en eervolle soldaat van de Frostwolf bent.$B$BJe tijd is weer gekomen, $N. Je hebt een nieuwe rang verdiend, en daarmee een nieuw insigne dat je hogere positie laat zien.$B$BLaat je insigne zien.",
  c = "<Warmaster Laggrond salueert.>$B$BGa, $N! Blijf de Frostwolf verdedigen. Deze oorlog moet gewonnen worden! Voor Drek'Thar! Voor de Warchief!",
  g = { {"Geëerd", "honored (eren)"}, {"verwacht", "expected (verwachten)"}, {"bewezen", "proven (bewijzen)"}, {"dappere", "brave (dapper)"}, {"eervolle", "honorable (eervol)"}, {"positie", "standing, position"}, {"verdedigen", "to defend"} },
},

[7165] = { en = "Earned Reverence", tier = 4,
  t = "Verdiend ontzag",
  p = "Zoveel doden. Bloed doordrenkt de velden. En toch... leef jij nog... Je hebt volgehouden. Je hebt onze legers naar veel overwinningen geleid. Daarom, soldaat, heb je een nieuwe rang verdiend.$b$bLaat je insigne zien.",
  c = "<Warmaster Laggrond brult.>$b$bMen vertelt al verhalen over je daden, soldaat. De Stormpike beeft van angst als jouw naam wordt uitgesproken. Ga door!",
  g = { {"ontzag", "reverence, awe"}, {"doordrenkt", "drenches (doordrenken)"}, {"volgehouden", "persevered (volhouden)"}, {"legers", "armies (leger)"}, {"overwinningen", "victories (overwinning)"}, {"brult", "roars (brullen)"}, {"daden", "deeds (daad)"}, {"beeft", "trembles (beven)"}, {"uitgesproken", "uttered (uitspreken)"} },
},

[7166] = { en = "Legendary Heroes", tier = 4,
  t = "Legendarische helden",
  p = "Je straalt gezag en kracht uit, $C. Verheven in de ogen van de Frostwolf - de vijand duikt ineen als jouw naam valt.$B$BSta op, Held van de Frostwolf. Sta op en word geëerd!$B$BLaat je insigne zien.",
  c = "Binnenkort is iedereen op het slagveld onder jouw waakzame oog. Het bevel over de Vallei en haar troepen zal van jou zijn!",
  g = { {"Legendarische", "legendary (legendarisch)"}, {"straalt", "radiates (uitstralen)"}, {"gezag", "authority, command"}, {"Verheven", "exalted"}, {"duikt ineen", "cowers (ineenduiken)"}, {"geëerd", "honored (eren)"}, {"waakzame", "watchful (waakzaam)"}, {"bevel", "command"} },
},

[7167] = { en = "The Eye of Command", tier = 4,
  t = "Het Eye of Command",
  p = "Drek'Thar zingt je lof. Heel Kalimdor gonst van de verhalen over je heldendaden. De Warchief straalt - je standvastige verdediging van onze clan heeft hem erg tevreden gemaakt.$b$bJe hebt het Eye of Command verdiend.$b$bLaat je insigne zien, Commandant $N.",
  c = "Gebruik de kracht van het insigne. Laat de vijand je woorden horen. De macht van de Horde staat buiten kijf!",
  g = { {"zingt je lof", "sings your praises"}, {"gonst", "buzzes (gonzen)"}, {"heldendaden", "heroic deeds (heldendaad)"}, {"straalt", "glows (stralen)"}, {"standvastige", "stalwart (standvastig)"}, {"verdediging", "defense"}, {"Commandant", "commander"}, {"macht", "might"}, {"staat buiten kijf", "is beyond question"} },
},

[7181] = { en = "The Legend of Korrak", tier = 4,
  t = "De legende van Korrak",
  d = "De binnengevallen Stormpike zijn niet de enige bedreiging in deze streek, soldaat. De oorlog in de Vallei wordt aan twee fronten gevoerd. Ook de kannibalistische Winterax-trollen strijden om de macht.$B$BZe worden geleid door Korrak the Bloodrager - een wreed en sluw beest.$B$BEen aanval op Korrak kan een verpletterende klap zijn voor de Winterax-clan. Dood het beest en je wordt beloond!",
  o = "Volgens de legende verschijnt de leider van de machtige Winterax-trollen wanneer hij maar wil, om verwoesting te zaaien onder de bewoners van Alterac Valley.$B$BAls Korrak zich laat zien, vernietig hem dan en keer terug naar Warmaster Laggrond.",
  g = { {"bedreiging", "threat"}, {"fronten", "fronts (front)"}, {"gevoerd", "waged (voeren)"}, {"kannibalistische", "cannibal (kannibalistisch)"}, {"wreed", "cruel"}, {"sluw", "cunning"}, {"verpletterende", "crushing (verpletteren)"}, {"klap", "blow"}, {"beloond", "rewarded (belonen)"}, {"verwoesting te zaaien", "to wreak havoc"}, {"bewoners", "inhabitants, denizens (bewoner)"} },
},

[7224] = { en = "Enemy Booty", tier = 4,
  t = "Buit van de vijand",
  d = "Als je tegen de vijand vecht, verzamel dan de stukjes van hun harnas en breng ze naar mij. Ik gebruik die stukjes om harnassen te maken voor onze eigen troepen!",
  o = "Breng 20 Armor Scraps naar Smith Regzar in Frostwolf Village.",
  p = "Hoe gaat de jacht, $N? Heb je stukjes harnas voor me?",
  c = "Deze zijn prima. Ik smelt ze om en lap ze op, en je zult nooit merken dat ze van die Stormpike-lafaards kwamen!$B$BBedankt, $N. En laat mij dat harnas van jou even oppoetsen...",
  g = { {"Buit", "booty, loot"}, {"harnas", "armor"}, {"harnassen", "suits of armor"}, {"smelt ze om", "melt them down (omsmelten)"}, {"lap ze op", "patch them up (oplappen)"}, {"merken", "notice"}, {"lafaards", "cowards (lafaard)"}, {"oppoetsen", "to polish up"} },
},

[7241] = { en = "In Defense of Frostwolf", tier = 4,
  t = "Ter verdediging van Frostwolf",
  d = "De oorlogstrommels klinken in een ver land, $c. De favoriete clan van je Warchief wordt aangevallen door de verraderlijke Stormpike Guard uit Ironforge.$B$BAls ik naar je kijk, zie ik dat je echt gehard bent in de strijd en klaar bent om de zaak van de Frostwolf op je te nemen.$B$BJij moet nu de volgende stap zetten in je ontwikkeling.$B$BTen noorden van Tarren Mill, in Alterac, vind je de ingang van Alterac Valley. Daar vind je Warmaster Laggrond. Haast je, $c, want de strijd is begonnen!",
  o = "Ga naar Alterac Valley, in de Alterac Mountains. Zoek Warmaster Laggrond - die buiten bij de ingang van de tunnel staat - en spreek met hem om je loopbaan als soldaat van de Frostwolf te beginnen. Je vindt Alterac Valley ten noorden van Tarren Mill, aan de voet van de Alterac Mountains.",
  c = "Wie soldaat van de Frostwolf wil worden, moet eerst op de proef worden gesteld...",
  g = { {"Ter verdediging van", "in defense of"}, {"oorlogstrommels", "war drums (oorlogstrommel)"}, {"verraderlijke", "nefarious, treacherous (verraderlijk)"}, {"gehard", "hardened, hardy"}, {"de zaak", "the cause"}, {"op je te nemen", "to take on (op je nemen)"}, {"ontwikkeling", "evolution, development"}, {"loopbaan", "career"}, {"aan de voet van", "at the base of"}, {"op de proef worden gesteld", "be tested"} },
},

[7281] = { en = "Brotherly Love", tier = 4,
  t = "Broederliefde",
  d = "Tragisch... Mijn broer staat tegenover mij op het slagveld: een commandant van de Stormpike.$B$BVan de vier Stormpike-commandanten is hij zonder twijfel de gevaarlijkste. Als hij wordt gedood, kan de Banshee Queen hem misschien veranderen zoals ze mij veranderde - hem laten zien hoe fout hij zit...$B$BDiep in vijandelijk gebied vind je mijn broer. Dood hem en kom terug bij mij. Ik vertrouw erop dat je deze missie kunt volbrengen, soldaat.$B$BEn, soldaat, ga niet alleen.",
  o = "Reis naar het gebied van de Stormpike en dood Commander Karl Philips. Keer terug naar Commander Louis Philips als de taak klaar is.$b",
  p = "Wat moet het hem pijn doen dat hij nog bij de levenden hoort, terwijl zijn geliefde broer tot volmaaktheid is opgestegen.",
  c = "Je heldendaden blijven niet onopgemerkt, $N.$B$BIk mag geen tijd verliezen als hij gered moet worden. We moeten contact opnemen met Sylvanas!",
  g = { {"Broederliefde", "brotherly love"}, {"Tragisch", "tragic"}, {"zonder twijfel", "undoubtedly"}, {"hoe fout hij zit", "the error of his ways"}, {"volbrengen", "to complete, accomplish"}, {"levenden", "the living"}, {"geliefde", "beloved"}, {"volmaaktheid", "perfection"}, {"opgestegen", "ascended (opstijgen)"}, {"onopgemerkt", "unnoticed"} },
},

[7302] = { en = "Fallen Sky Lords", tier = 4,
  t = "Gevallen heren van de lucht",
  d = "Onze luchtsteun ligt in puin, $N. De Wing Commanders zijn boven vijandelijk gebied neergeschoten. Je moet uitzoeken wat er met hen is gebeurd, zodat we een redding kunnen proberen!$B$BGuse is voor het laatst gezien terwijl hij over de Icewing Bunker vloog. Jeztor's War Rider is gezien bij de houtzagerij van de Stormpike. Mulverick... die roekeloze dwaas is gezien toen hij neerstortte bij de Dun'Baldar North Bunker.$B$BMeer informatie heb ik niet. Op pad! Doorzoek de gebieden grondig.",
  o = "Zoek uit wat er is gebeurd met Wing Commander Guse, Wing Commander Jeztor en Wing Commander Mulverick. Keer terug naar Commander Mulfort als je je missie hebt volbracht.",
  p = "Hoe staat de zoektocht ervoor, soldaat?",
  c = "Goed gedaan! De informatie die je hebt gevonden is van onschatbare waarde voor onze zaak.",
  o1 = "Plek van Guse ontdekt",
  o2 = "Plek van Jeztor ontdekt",
  o3 = "Plek van Mulverick ontdekt",
  g = { {"luchtsteun", "air support"}, {"ligt in puin", "is in shambles"}, {"neergeschoten", "shot down (neerschieten)"}, {"redding", "rescue"}, {"roekeloze", "reckless (roekeloos)"}, {"neerstortte", "crashed (neerstorten)"}, {"Doorzoek", "search through (doorzoeken)"}, {"grondig", "thoroughly"}, {"volbracht", "completed (volbrengen)"}, {"van onschatbare waarde", "invaluable"} },
},

[7361] = { en = "Favor Amongst the Darkspear", tier = 4,
  t = "Gunst bij de Darkspear",
  d = "<Najak gromt.>$B$BVoordat de nachtelfen bestonden, was er de trol. Uit de trol zijn de nachtelfen voortgekomen.$B$BHun opstandige aanvallen op mijn volk dulden we niet. Staghelm wil ons uitroeien - geen spoor achterlaten van hen die hem en zijn soort hebben voortgebracht. Dat zal niet gebeuren!$B$BVoor elke nachtelf die je doodt en onthoofdt, geeft Najak je gunst bij de Darkspear. Het nieuws van je daden zal zich verspreiden over Kalimdor en de Eastern Kingdoms. Ga nu en dien de Darkspear!",
  o = "Je hebt de opdracht gekregen om vijandelijke nachtelf-spelers te doden in Alterac Valley.$B$BDood een nachtelf en keer terug naar Najak Hexxen in Frostwolf Keep met een Severed Night Elf Head.",
  p = "Ze willen ons uitroeien? Zij zijn het die zullen worden uitgeroeid.",
  c = "$N, dit is er maar een van duizenden. Toch goed gedaan.",
  g = { {"Gunst", "favor"}, {"gromt", "snarls (grommen)"}, {"voortgekomen", "came from (voortkomen)"}, {"opstandige", "mutinous (opstandig)"}, {"uitroeien", "to wipe out, exterminate"}, {"spoor", "trace"}, {"soort", "ilk, kind"}, {"voortgebracht", "bore, produced (voortbrengen)"}, {"onthoofdt", "decapitate (onthoofden)"}, {"verspreiden", "spread"}, {"dien", "serve (dienen)"}, {"uitgeroeid", "exterminated (uitroeien)"} },
},

[7362] = { en = "Ally of the Tauren", tier = 4,
  t = "Bondgenoot van de tauren",
  d = "De Elder Crone heeft me naar dit oorlogsgebied gestuurd om de andere volken te onderzoeken. Om precies te zijn moet ik monsters van gnomen verzamelen. Magatha is vooral geïnteresseerd in hoe goed ze overleven. Ja, de gnomen - hoe zielig zwak en piepklein ook - zijn opvallend taai, zowel in als buiten het gevecht.$B$BGelukkig voor jou zoek ik ruwe types die Magatha's opdrachten willen uitvoeren. Kom terug bij mij met plukjes gnomenhaar, en de tauren zullen je als bondgenoot kennen.",
  o = "Je hebt de opdracht gekregen om vijandelijke gnoom-spelers te doden in Alterac Valley.$B$BDood een gnoom en keer terug naar Ravak Grimtotem in Frostwolf Keep met een Tuft of Gnome Hair.",
  p = "Het kan me niet schelen waar het haar vandaan komt, $R.",
  c = "Ja, dit is zeker gnoom. Goed gedaan, $R, maar er is nog meer werk te doen.",
  g = { {"Bondgenoot", "ally"}, {"oorlogsgebied", "warzone"}, {"volken", "races, peoples (volk)"}, {"monsters", "samples (monster)"}, {"overleven", "survive"}, {"zielig", "pitifully"}, {"piepklein", "tiny, minuscule"}, {"opvallend taai", "remarkably resilient"}, {"ruwe types", "ruffians"}, {"uitvoeren", "carry out"}, {"plukjes", "tufts (plukje)"}, {"Het kan me niet schelen", "I don't care"} },
},

[7363] = { en = "The Human Condition", tier = 4,
  t = "De menselijke conditie",
  d = "Mensen zijn zo ontzettend walgelijk.$B$B<Commander Philips trekt een vies gezicht.>$B$BHet is waar dat ik een soldaat van de Frostwolf ben, maar ik blijf een dienaar van Sylvanas.$B$BTijdens mijn dienstperiode doe ik er wat extra werk naast voor de Dark Apothecaries van de Undercity.$B$BIk moet botsplinters van mensen verzamelen die gebruikt worden om de menselijke conditie te genezen.$B$BIk mag die taak doorgeven aan mijn ondergeschikten.$B$BZoek ze. Dood ze. Breng hun botsplinters naar mij.",
  o = "Je hebt de opdracht gekregen om vijandelijke mens-spelers te doden in Alterac Valley.$B$BDood een mens en keer terug naar Commander Louis Philips (die heen en weer loopt tussen de frontlinie en Frostwolf Keep) met een Human Bone Chip.$B$BEen geneesmiddel voor de menselijke conditie is dichtbij!",
  p = "Ja, het is waar. Mijn broer is een mens. Schandelijk... Een smet op mijn bijna vlekkeloze staat van dienst.",
  c = "Het zou makkelijker zijn als ze hun ziekte gewoon accepteerden en zich overgaven aan jouw genezende aanraking. Het zou waarschijnlijk ook minder leuk zijn. Ga door! We genezen ze, op de ene of de andere manier.",
  g = { {"conditie", "condition"}, {"ontzettend", "utterly, terribly"}, {"walgelijk", "detestable, disgusting"}, {"trekt een vies gezicht", "grimaces"}, {"dienaar", "servant"}, {"dienstperiode", "tour of duty"}, {"botsplinters", "bone chips (botsplinter)"}, {"ondergeschikten", "subordinates (ondergeschikte)"}, {"geneesmiddel", "cure, medicine"}, {"Schandelijk", "shameful"}, {"smet", "stain"}, {"vlekkeloze staat van dienst", "immaculate record"}, {"zich overgaven", "gave in (zich overgeven)"}, {"aanraking", "touch"} },
},

[7368] = { en = "Defusing the Threat", tier = 4,
  t = "De dreiging onschadelijk maken",
  d = "Ik weet alles van landmijnen. Ik ben tenslotte degene die hier alle mijnen aan de frontlinie legt.$B$BAls je de mijnenvelden van de Stormpike onschadelijk wilt maken, hoef je alleen hun explosievenexpert te doden. Die laffe dwerg verstopt zich vast in de eerste toren op het Field of Strife. Schakel hem uit, dan komen die landmijnen niet terug nadat ze onschadelijk zijn gemaakt.$B$BAls je hem doodt, kom dan hier terug en laat het me weten. Geen goede daad mag onbeloond blijven.",
  o = "Zoek de Stormpike Explosives Expert en dood hem. Keer terug naar de Frostwolf Explosives Expert als de taak klaar is.",
  g = { {"dreiging", "threat"}, {"onschadelijk maken", "to defuse, disarm"}, {"landmijnen", "landmines (landmijn)"}, {"tenslotte", "after all"}, {"mijnenvelden", "mine fields (mijnenveld)"}, {"explosievenexpert", "explosives expert"}, {"laffe", "cowardly (laf)"}, {"Schakel hem uit", "take him out (uitschakelen)"}, {"onbeloond", "unrewarded"} },
},

[7381] = { en = "The Return of Korrak", tier = 4,
  t = "De terugkeer van Korrak",
  d = "Het is waar dat Korrak is gedood, maar er blijft één vraag over: blijft hij ook dood? Trollen staan bekend om hun bovennatuurlijke stammagie. Het zou me niet verbazen als de gevallen leider uit de dood werd opgewekt om weer over zijn clan te heersen.$B$BJe weet wat je moet doen als dat ooit gebeurt.$B$B<Warmaster Laggrond maakt met zijn wijsvinger een snijdende beweging langs zijn keel.>$B$BEn deze keer wil ik zijn schedel. Houd je ogen open, soldaat.$B$BIngerukt!",
  o = "Als Korrak the Bloodrager terugkeert naar het Field of Strife, zoek hem dan op en vernietig hem.$B$BBreng de Skull of Korrak naar Warmaster Laggrond in de Hillsbrad Foothills.",
  g = { {"terugkeer", "return"}, {"staan bekend om", "are notorious for"}, {"bovennatuurlijke", "other-worldly (bovennatuurlijk)"}, {"stammagie", "tribal magic"}, {"verbazen", "surprise"}, {"opgewekt", "raised (opwekken)"}, {"heersen", "rule"}, {"wijsvinger", "index finger"}, {"snijdende", "cutting (snijden)"}, {"keel", "throat"}, {"schedel", "skull"}, {"Ingerukt", "dismissed"} },
},

[7385] = { en = "A Gallon of Blood", tier = 4,
  t = "Een gallon bloed",
  d = "Je kunt ook grotere hoeveelheden bloed van onze vijanden aanbieden. Ik neem graag offers van een gallon aan, $N.",
  o = "null",
  p = "Je moet onze vijanden neerslaan en mij hun bloed brengen.",
  c = "Het bloed van onze vijanden is vergoten. Ik meng dit bloed met de rest die is verzameld. Zodra het offer compleet is, zal de Ice Lord deze Stormpike-honden de volle woede van de Frostwolf Clan laten zien!",
  g = { {"gallon", "gallon (about 4 litres)"}, {"hoeveelheden", "quantities (hoeveelheid)"}, {"aanbieden", "to offer"}, {"offers", "offerings (offer)"}, {"neerslaan", "strike down"}, {"vergoten", "shed (vergieten)"}, {"meng", "mix (mengen)"}, {"woede", "wrath"} },
},

[7401] = { en = "Wanted: DWARVES!", tier = 4,
  t = "Gezocht: DWERGEN!",
  d = "In opdracht van Sergeant Yazra Bloodsnarl moeten alle dwergen op het slagveld meteen worden gedood.$B$BAls je een dwerg in een gevecht doodt, ruk dan de ruggengraat eruit. Laat een ruggengraatloze hoop stank en rotting achter als waarschuwing voor iedereen die zich tegen de macht van de Frostwolf durft te verzetten.$B$BKeer terug naar Sergeant Yazra Bloodsnarl met bewijs van je heldendaden.",
  o = "Je hebt de opdracht gekregen om vijandelijke dwerg-spelers te doden in Alterac Valley.$B$BDood een dwerg en ruk de ruggengraat eruit. Breng de Dwarf Spine naar Sergeant Yazra Bloodsnarl in Frostwolf Keep.",
  p = "Ik handel in ironie in het groot, soldaat.",
  c = "Je hebt nu een vergunning om dwergen bij dozijnen te vernietigen, $C!$B$B<Yazra staart even in de verte.>$B$BJe eerste keer ruggengraat-trekken vergeet je nooit...",
  g = { {"Gezocht", "wanted"}, {"In opdracht van", "by order of"}, {"ruk", "rip (rukken)"}, {"ruggengraat", "spine"}, {"ruggengraatloze", "spineless (ruggengraatloos)"}, {"stank", "stink"}, {"rotting", "rot"}, {"zich verzetten", "to oppose"}, {"bewijs", "proof"}, {"in het groot", "wholesale"}, {"vergunning", "license"}, {"bij dozijnen", "by the dozen"}, {"staart", "stares (staren)"} },
},

