[8369] = { en = "Invaders of Alterac Valley", tier = 4,
  t = "Indringers in Alterac Valley",
  d = "Luister goed, $N. Wat je ook hebt gehoord over de strijd in Alterac Valley, één ding blijft waar: de Stormpike Expedition is het gebied van de Frostwolf binnengevallen. De dag dat wij de Alliance Horde-land laten binnenvallen zonder krachtig terug te slaan, is de dag dat ik mijn bijl aan de wilgen hang en de rest van mijn leven in schaamte leef. Ga en verdrijf de indringers!",
  o = "Breng 3 Alterac Valley Marks of Honor naar een Horde Warbringer buiten de slagvelden.",
  p = "Welk nieuws breng je uit de landen van de Frostwolves? Hoe staat de strijd om Alterac Valley ervoor?",
  c = "Je hebt grote moed getoond bij het beschermen van ons land in Alterac Valley! Ik zal mijn meerderen over je daden vertellen.",
  g = { {"Indringers", "invaders (indringer)"}, {"krachtig", "forceful"}, {"terug te slaan", "to strike back (terugslaan)"}, {"mijn bijl aan de wilgen hang", "hang up my axe (aan de wilgen hangen)"}, {"schaamte", "shame"}, {"verdrijf", "expel, drive out (verdrijven)"}, {"slagvelden", "battlegrounds (slagveld)"}, {"moed", "bravery"}, {"getoond", "shown (tonen)"}, {"meerderen", "superiors (meerdere)"} },
},

})

